import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.B_k70FqT.js";const g=JSON.parse('{"title":"Example Apps","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/examples.md","filePath":"en/guide/examples.md","lastUpdated":1795867940000}'),o={name:"en/guide/examples.md"};function d(n,e,l,r,p,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="example-apps" tabindex="-1">Example Apps <a class="header-anchor" href="#example-apps" aria-label="Permalink to &quot;Example Apps&quot;">​</a></h1><p>The repo ships two apps you can run directly: a full-featured editor and a minimal integration example. They also serve as inputs for the example snapshot tests — whether a graph loads and whether serialization is stable is covered by <code>pnpm test</code>.</p><h2 id="full-editor-apps-editor" tabindex="-1">Full editor <code>apps/editor</code> <a class="header-anchor" href="#full-editor-apps-editor" aria-label="Permalink to &quot;Full editor `apps/editor`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @litegraph/editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>On top of the minimal example, the editor adds:</p><ul><li>Toolbar: run / pause, save / load, clear, maximize, mini preview, live mode toggle;</li><li>Example dropdown: load built-in demos and <code>public/examples/*.json</code> with one click; the view auto-fits the loaded graph;</li><li>Local recovery: the current graph is backed up to <code>localStorage</code> when the page unloads and restored on the next visit (you can also switch back from the dropdown);</li><li>Toolbar <code>Fit</code> button: fit the whole graph into view at any time, including inside a subgraph;</li><li>Node search box: search nodes by type / title and drag them onto the canvas to create;</li><li>Context menu, properties panel, widget interaction, box selection, snap alignment, groups;</li><li>Two editor-only plugins: <code>features/*</code> (ports / widgets / shapes demo nodes) and <code>circuit/*</code> (oscillator, LED), installed via <code>LiteGraph.use()</code> in <code>apps/editor/src/Editor.ts</code>.</li></ul><h3 id="built-in-demos" tabindex="-1">Built-in demos <a class="header-anchor" href="#built-in-demos" aria-label="Permalink to &quot;Built-in demos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Contents</th></tr></thead><tbody><tr><td><code>Basic1</code></td><td>One constant into one watch</td></tr><tr><td><code>Basic2</code></td><td>Two constants, each into its own watch</td></tr><tr><td><code>Basic3</code></td><td>Two constants + a math operation + three watches</td></tr><tr><td><code>Widgets</code></td><td>Knob → progress bar, toggle → watch, button event → log</td></tr><tr><td><code>Events</code></td><td>Timer → counter → watch, logging every change event</td></tr><tr><td><code>Subgraph</code></td><td>Inner graph &quot;Add 10&quot;: constant → subgraph → watch; double-click the subgraph node to enter/leave</td></tr><tr><td><code>Audio1</code></td><td><code>audio/source</code> → <code>audio/destination</code></td></tr><tr><td><code>Audio2</code></td><td>Source + knob + analyser + visualization</td></tr><tr><td><code>Audio3</code></td><td>Audio2 plus an oscilloscope</td></tr><tr><td><code>Circuit1</code></td><td><code>circuit/oscillator</code> → <code>circuit/led</code></td></tr></tbody></table><h3 id="bundled-json-examples" tabindex="-1">Bundled JSON examples <a class="header-anchor" href="#bundled-json-examples" aria-label="Permalink to &quot;Bundled JSON examples&quot;">​</a></h3><p>These files live in <code>apps/editor/public/examples/</code> and are loaded by the editor via <code>graph.load(url)</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>features.json</code></td><td>All four demo node types: <code>features/slots</code>, <code>features/widgets</code>, <code>features/shape</code> and <code>features/properties_editor</code></td></tr><tr><td><code>benchmark.json</code></td><td>A performance benchmark graph with many nodes and links</td></tr><tr><td><code>subgraph.json</code></td><td>Subgraphs with <code>graph/input</code> and <code>graph/output</code></td></tr><tr><td><code>audio.json</code></td><td>A fairly complete audio processing chain</td></tr><tr><td><code>audio_delay.json</code></td><td>Delay node example</td></tr><tr><td><code>audio_reverb.json</code></td><td>Reverb node example</td></tr><tr><td><code>midi_generation.json</code></td><td>MIDI generation, quantization and playback</td></tr></tbody></table><h3 id="live-mode" tabindex="-1">live mode <a class="header-anchor" href="#live-mode" aria-label="Permalink to &quot;live mode&quot;">​</a></h3><p>The <code>LIVE</code> button on the right side of the editor toolbar toggles <code>graphCanvas.live_mode</code>: it hides the grid, node borders, ports and title bars, keeping only node-drawn content. Handy when using the editor as a runtime UI, for example for audio visualization or parameter panels.</p><h2 id="minimal-example-apps-example-minimal" tabindex="-1">Minimal example <code>apps/example-minimal</code> <a class="header-anchor" href="#minimal-example-apps-example-minimal" aria-label="Permalink to &quot;Minimal example `apps/example-minimal`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @litegraph/example-minimal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>src/main.ts</code> is only a few dozen lines: import core and the <code>basic</code> node pack, import styles, create an <code>LGraph</code> and an <code>LGraphCanvas</code>, drop in a <code>ConstantNumber</code> and a <code>Watch</code>, connect them and call <code>graph.start()</code>. It demonstrates:</p><ul><li>importing <code>@gausszhou/litegraph-core/style.css</code> explicitly;</li><li>creating nodes from classes instead of type strings (<code>LiteGraph.createNode(ConstantNumber)</code>);</li><li>redrawing the canvas in <code>onAfterExecute</code>;</li><li>listening for window resize and calling <code>graphCanvas.resize()</code>.</li></ul><p>This example is also a snapshot baseline: the test builds <code>ConstantNumber(4.5) → Watch</code> the same way, asserts 2 nodes and 1 link, and serializes the result into a snapshot.</p><h2 id="importing-and-exporting-graphs" tabindex="-1">Importing and exporting graphs <a class="header-anchor" href="#importing-and-exporting-graphs" aria-label="Permalink to &quot;Importing and exporting graphs&quot;">​</a></h2><p>What the editor saves is exactly the result of <code>graph.serialize()</code>; restore it in any environment like this:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> graph</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LGraph</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(json));</span></span></code></pre></div><p>Loading a graph that contains unknown node types does not throw: <code>configure()</code> returns <code>true</code> and replaces the missing nodes with error nodes. To spot missing packs early, check the return value:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (graph.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data)) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The graph has unregistered node types; install the matching node pack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="example-snapshot-regression" tabindex="-1">Example snapshot regression <a class="header-anchor" href="#example-snapshot-regression" aria-label="Permalink to &quot;Example snapshot regression&quot;">​</a></h2><p><code>packages/tests/src/ExamplesSnapshotTests.ts</code> brings the examples into automated regression, covering 18 cases:</p><ul><li>every JSON file in <code>apps/editor/public/examples/*.json</code>: <code>configure()</code> returns <code>false</code>, the node count matches the file, and serialize → <code>configure()</code> again → serialize again is deeply equal;</li><li>the 10 function-style demos in <code>apps/editor/src/demos.ts</code>: node count &gt; 0 after building and serialization is stable;</li><li>the minimal example baseline: <code>ConstantNumber(4.5) → Watch</code>.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # everything</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gausszhou/litegraph-tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Snapshots live in <code>packages/tests/src/__snapshots__/main.ts.snap</code>. Update them <strong>only when you are sure the serialization format change is intentional</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gausszhou/litegraph-tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span></span></code></pre></div><p><code>pnpm demo:smoke</code> also opens the built demo in the local Chrome / Chromium, switches through every example and checks that the canvas differs from the Empty state, that node and link counts are greater than zero, that every node is inside the viewport after Fit, and that there are no JS exceptions or <code>console.error</code> calls. Add <code>-- --screenshots</code> to write a PNG per example to <code>artifacts/demo-smoke/</code>; CI runs this and uploads the screenshots as a build artifact (build the editor first).</p><p>To add an example:</p><ol><li>Put the graph JSON in <code>apps/editor/public/examples/</code>;</li><li>Register it in the <code>addDemo(...)</code> list in <code>apps/editor/src/main.ts</code>;</li><li>If it uses editor-only nodes (<code>features/*</code>, <code>circuit/*</code>), make sure the plugin is installed in <code>Editor.ts</code>;</li><li>Run <code>pnpm test</code>; the first run creates a snapshot for the new file, so run it again to confirm stability, then commit the snapshot.</li></ol>',32)])])}const u=a(o,[["render",d]]);export{g as __pageData,u as default};
